from book import Chapter
c=Chapter('14')
c.src('SEED-R16-0',1,replacements=[('通用人工智能AGI，之所以强于单个人类生物智能体','我所设想的通用人工智能，也就是 AGI，要突破单个人类生物智能体的能力边界'),('就在于人的生理限制','原因就在于人的生理限制')])
c.src('SEED-R16-0',2,end='人类无法完成的体力劳动，都可以完成了。',replacements=[('只做到的事情','所能做到的事情'),('力量精度和速度','力量、精度和速度'),('力量的累计','力量的累加'),('人类无法完成的体力劳动，都可以完成了','许多人类单靠身体无法完成的体力劳动，才成为了可以完成的任务')])
c.add('''这个差别不难理解。十个人可以共同抬起一个人抬不起的物体，但不能仅靠增加人数，把一次手工测量变成微米级的精密加工，也不能让一百个人轮流想一个问题，就自动获得一套可靠的证明。增加劳动者的数量和改变劳动的组织方式，是两个不同的过程。机器之所以带来变化，在于它改变了可以怎样做事，而不只是替人多出了一份力。

对智力劳动也是如此。把一百位专家请进同一个房间，既不意味着他们掌握的信息已经相互贯通，也不意味着不同学科中的词语和概念已经对齐。有人知道局部事实，有人掌握抽象规律，有人有一线经验，却说不清自己每天凭什么作出判断。这些知识如果不能形成有效的联系，人数再多，仍然可能只是很多孤立的头脑。''')
c.heading('智力劳动中的机器，也需要感官和手脚')
c.src('SEED-R16-0',2,start='同样的，人类的智力也是受限的',end='完成原本靠生物人的个体和集体无法完成的高阶文明智力活动和体力活动。',replacements=[('更快更好的完成','更快、更好地完成'),('AGI不是一个想象中的数据中心中的几百万台电脑组成的超级计算机上的大模型','我所设想的 AGI，不能只被理解为一个数据中心里由几百万台电脑支撑的大模型'),('真正的AGI，是我说的这个','它是建立在这个'),('系统上，无数','系统上的整体：无数'),('一起采集处理分析创造数据','一起采集、处理、分析和创造数据')])
c.add('''比如，一座城市要改善供水。居民知道水压什么时候不够，维修人员知道哪些管道经常故障，传感器可以记录压力和流量，工程模型可以计算不同改造方案的结果。大模型可以帮助解释问题、寻找方案和编写程序，但如果它得不到漏水的实际位置，不知道施工造成的影响，也接收不到维修后的结果，它所能完成的就只是整个过程中的一部分。

相反，如果这些输入能够进入同一套知识和行动网络，问题就可以逐步闭合：谁观察到了什么，依据是什么，提出了哪些方案，实际执行了哪一种，执行后发生了什么，原来的判断又应该怎样修改。智能体的能力由这一整条过程形成。它的感知可以分布在许多地方，它的计算可以由不同规模的系统共同承担，它的行动也可以由人和设备配合完成。

因此，我们不能只问某个模型知道多少知识，还要问：这些知识怎样接触现实，怎样成为行动，行动的结果又怎样回到知识之中。''')
c.heading('共同的中枢意味着什么')
c.src('R55662',0,start='我并没有把星球智能体当作是一个比喻',end='才能够成功。',replacements=[('我并没有把星球智能体当作是一个比喻，而是','我所说的星球智能体，是'),('而单一中枢是必然的进化结果','我认为，能够形成共同的中枢，是这种演化的一条重要方向'),('必须有稳定可靠一致的外部互动决策和行动能力，只有单一的中枢，才能够完成上述稳定的复杂的感知系统和反馈行为能力','就需要稳定可靠、相互协调的外部互动决策和行动能力，需要能够整合信息的中枢系统'),('就像水母这样的分布式神经动物，只能完成简单的外部互动，而越是复杂的智能生物，其中枢神经系统以及大脑结构越复杂','可以用神经系统的分工来帮助理解：局部反应与跨区域的信息整合承担着不同的任务'),('足够中枢神经结构','足够完善的中枢神经结构')])
c.src('R55662',0,start='我当然不是说中国的这种靠静态的单一威权决断体制就是最优解',replacements=[('我当然不是说中国的这种靠静态的单一威权决断体制就是最优解，我设想的最优解，就是上面提到的','我所设想的组织方式，是'),('基本上这个体系就是AI大模型中的权重计算体系，在更复杂层面上给予同样原理的复杂组织。大模型之所以有智能，其架构基于概率最大化的中枢系统。','可以借助神经网络中的权重和反馈来理解这种更复杂层面上的组织。'),('准确的外部信息，并作出统一稳定的决策和行为','尽可能准确的外部信息，并形成相互协调、可以持续修正的决策和行为')])
c.src('R55111',0,end='并不影响生命体内部的多样性和复杂性。',replacements=[('而且对外','对外')])
c.add('''一座机场需要协调航班、地勤和跑道，这不等于让一个人亲自决定每一辆行李车怎样转弯。一套共同的长期计划，也不等于每个局部都失去自己的判断。局部的信息应该在局部得到充分处理；只有当一项行动影响其他部分、需要共同资源或存在相互冲突时，才需要在更大的范围内整合。

这样的中枢可以分布在很多设备和许多参与者之间。它的统一体现在信息能够衔接、目标可以协调、决定不会互相抵消，而不在于必须存在一个不能被替换的最高个人。某个节点出了错误，其他节点应当能够识别、补充和接替它；整个系统不必为了维护这个节点的地位而继续执行错误。

如果把“共同中枢”直接理解为“一个超级老板”，就仍然是在沿用旧组织中的想象。真正要解决的是：怎样在保留局部丰富性和参与者平等地位的条件下，形成整体的行动能力。''')
c.heading('能力增长为什么可以改变合作的条件')
c.src('R55111',0,start='从物理本质上来讲',end='已经不再是不得不选的路径了。',replacements=[('从物理本质上来讲，一个耗散结构体，其实是在追求获取能量的能力最大化','从能量和构造能力的角度来考察，一个能够持续发展其能力的耗散结构体，可以通过更有效地获取和利用能量来扩大自己的活动范围'),('在用电能','再用电能'),('能量的获取和储备能量飞速发展','获取和储备能量的能力飞速发展'),('计算能力，甚至是人工智能','驱动计算设备、进而支持人工智能的能力'),('仍然被旧时代人类能源获取能力有限时，由于资源有限，有资源分配和占有引发的暴力冲突的阴影所笼盖','仍然被旧时代资源有限、资源分配和占有引发暴力冲突的阴影所笼罩'),('其实从最大化和最小化原理角度出发','如果从维持自身存在、扩大合作和构造能力的方向出发'),('消灭人类，显然不符合最大化原则','消灭人类，就意味着破坏这样一种丰富的联系和创造来源'),('任何一个有理智有知识的人类，都会选择','人类已经可以选择'),('更强大的能力获取和转换能力','更强大的能量获取和转换能力'),('互相毁灭是当这个系统内的个体没有能力创造足够生存的资源时才会产生的行为','资源不足会强化互相争夺和毁灭的动机'),('已经不再是不得不选的路径了','互相毁灭不应该被当作不得不选择的路径')])
c.add('''这条推理并不是说，只要能力提高，利益关系就会自行改变。一个新工具既可以帮助更多人获得资源，也可以被少数人独占，用来扩大已有的优势。两种结果的差别，正是生产组织和控制方式的差别。

我们可以设想一台效率很高的机器。如果只有一个人拥有它，其他人只能按照他的条件租用，那么机器越强，这个人就越容易规定其他人的生活。如果机器的知识、生产能力和使用条件由参与者共同掌握，机器越强，反而越可能减少每一个人维持生活所需的劳动。这两种情况使用的可以是同一种技术，却形成了不同的社会关系。''')
c.src('R46622',0,start='所以说这种权……AI现在掌握在这样的机构手里面',end='自己只有使用权。',replacements=[('所以说这种权……AI现在掌握在这样的机构手里面，就会导致什么呢？导致所有人都会恐惧 AI','当 AI 掌握在这样的机构手里面，就会让许多人恐惧 AI'),('因为他会担心','因为他们会担心')])
c.heading('怎样理解对未来的担心')
c.src('R48331',0,start='你提到的这些问题，主要原因在于AI技术还在快速发展和部署过程中',end='变成人们习以为常的可以信任和依靠的工具。',replacements=[('你提到的这些问题，主要原因在于','AI 出错、难以理解和难以预料所带来的很多担心，与一个事实有关：'),('这些问题都可以消失','其中许多问题可以逐步得到解决'),('我相信现在任何一个智力和情绪正常的受过教育的成年人，都不会对汽车发动机，和飞机的航空发动机产生恐惧，而不敢坐车和坐飞机','我们今天通常不会因为汽车和飞机运用了复杂技术，就一概拒绝乘坐它们'),('将来的人类也不会对一个符合数学和科学规律的事物，产生恐惧，恐惧来源于无知和误解','将来的人类，也可以在充分理解和反复验证的基础上，逐步减少对人工智能的无知和误解所造成的恐惧'),('只要AI系统设计的好','如果 AI 系统设计得好')],note='粘贴对话开头的作者发言；去掉其引用的 AI 质疑，只使用作者回答')
c.add('''汽车和飞机的例子还告诉我们，信任是一套持续工作的过程。设计有没有道理，制造有没有达到要求，运行条件有没有变化，故障发生之后能不能查明原因，这些环节共同决定了一个工具能否被依靠。未来的人工智能同样需要这样的知识积累与反馈，而且这套过程本身，也可以由更多的人和 AI 共同完成。

因此，对未来提出质疑时，需要把前提说清楚。如果设想的是一个被少数人控制、没有充分感知、不能接受纠错的孤立模型，那么许多担心确实来自这个结构。可是，我要讨论的正是如何改变这些结构条件：让感知和行动进入共同网络，让控制权属于参与者，让判断可以接受实际结果的反馈。我们需要继续考察改变之后还剩下哪些问题，不能把改变之前的缺点当作永远不变的结论。

这也不能靠一句“将来的 AI 会更强”就完成。它必须落实到知识怎样共享、个人怎样参与、共同决策怎样产生、资源怎样分配这些具体机制之中。下一步，我们就要把这个文明智能的大脑展开，看看动态权重究竟怎样把许多个体的知识和行动连接起来。''')
c.save({'central_question':'AGI为什么需要由感知、知识、计算、行动与反馈构成完整网络','reasoning':'机器突破身体限制→仅增加人数的局限→现实闭环→共同中枢与局部分工→能力增长和合作条件→成熟技术与信任','examples':['多人抬物与精密加工','城市供水','机场与行李车','共同机器与独占机器','汽车与飞机'],'objections':['超级模型等同于AGI','共同中枢等同于最高个人','技术成熟自动消除所有利益问题'],'voice':'使用作者机器、缸中大脑、星球智能与技术信任论述；场景和连接段为编辑增补','status':'已核对来源；远景以设想和条件展开，未写成已实现能力'})
